#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-give-up-within-a-time-budget. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site hang
printf '%s\n' 'report ready' > site/report.txt
printf '%s\n' 'report ready' > hang/report.txt
cat > timed.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Runs curl with the arguments after the first two and says whether the whole command,
# every attempt and every wait, took from MIN to under MAX seconds.
# Usage: sh timed.sh MIN MAX CURL-ARGUMENTS...
min=$1; max=$2; shift 2
start=$(date +%s)
curl "$@"
code=$?
end=$(date +%s)
elapsed=$((end - start))
if [ "$elapsed" -ge "$min" ] && [ "$elapsed" -lt "$max" ]; then
  echo "exit $code within $min to $max seconds"
else
  echo "exit $code after $elapsed seconds"
fi
EOF
surl -v --log-file surl.log --directory site --fault "delay;ms=1500" --fault "error;scheme=http;reply=503" http://127.0.0.1:8080/ &
sleep 1
curl --no-progress-meter -f --retry 10 --retry-delay 1 --retry-max-time 5 -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/report.txt || true
kill $(jobs -p)
